UPDATE T_LH_CHIP_STOCK
SET IS_DELETE = 1,
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = #{updateTime}
WHERE FACTORY_CODE = #{factoryCode}
  AND DATA_SOURCE = #{dataSource}
  AND IS_DELETE = 0

UPDATE T_LH_CHIP_STOCK
SET FINISH_QTY = FINISH_QTY + #{delta},
    DATA_VERSION = #{newVersion},
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = CURRENT_TIMESTAMP
WHERE FACTORY_CODE = #{factoryCode}
  AND CHIP_CODE = #{chipCode}
  AND IS_DELETE = 0

      AND DATA_VERSION = #{expectedVersion}

UPDATE T_LH_CHIP_STOCK
SET FINISH_QTY = #{finishQty},
    DATA_VERSION = #{newVersion},
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = CURRENT_TIMESTAMP
WHERE FACTORY_CODE = #{factoryCode}
  AND CHIP_CODE = #{chipCode}
  AND IS_DELETE = 0

      AND DATA_VERSION = #{expectedVersion}
